task.en:
Write a program that uses goto statements and only the following three printf statements to simulate a nested looping structure that prints a square of asterisks as shown below:

printf("%s", "*");
printf("%s", " ");
printf("%s", "\n");

*****
*   *
*   *
*   *
*****

example.code:
#include <iostream>
#include <cstdlib>

int main() {
    const std::size_t initial_count = 6;
    // Cấp phát mảng 6 phần tử nguyên, được khởi tạo về 0
    int* arr = static_cast<int*>(std::calloc(initial_count, sizeof(int)));
    if (!arr) {
        std::cerr << "Allocation failed\n";
        return 1;
    }

    // Gán dữ liệu thử nghiệm
    for (std::size_t i = 0; i < initial_count; ++i) {
        arr[i] = static_cast<int>((i + 1) * 10);
    }

    // Giảm kích thước còn một nửa (3 phần tử) theo bài tập 14.6
    const std::size_t half_count = initial_count / 2;
    int* temp = static_cast<int*>(std::realloc(arr, half_count * sizeof(int)));
    if (temp != nullptr) {
        arr = temp; // Cập nhật an toàn sau khi kiểm tra
    } else {
        std::cerr << "Reallocation failed\n";
        std::free(arr);
        return 1;
    }

    // In nửa mảng còn lại
    for (std::size_t i = 0; i < half_count; ++i) {
        std::cout << arr[i] << (i + 1 < half_count ? " " : "\n");
    }

    std::free(arr);
    return 0;
}

#include <cstdio>

int main() {
    int r = 0;

row_loop:
    if (r >= 5) goto end_program;
    {
        int c = 0;
    col_loop:
        if (c >= 5) goto next_row;

        // Mô phỏng vẽ hình vuông 5x5 chỉ dùng đúng 3 lệnh printf theo bài 14.8
        if (r == 0 || r == 4 || c == 0 || c == 4) {
            std::printf("%s", "*");
        } else {
            std::printf("%s", " ");
        }

        ++c;
        goto col_loop;
    }

next_row:
    std::printf("%s", "\n");
    ++r;
    goto row_loop;

end_program:
    return 0;
}
